#!/usr/bin/env python3
"""Generate the C VM maps from the exhaustively shared-Canonicalize-checked Go maps."""
import pathlib
import re
root = pathlib.Path(__file__).resolve().parents[3]
source = (root / 'internal/regexp/canonicalize.go').read_text()
output = ['// Generated by internal/regexp/testdata/generate-native-folds.py.', '// Node-verified Unicode 17.0.0. https://www.unicode.org/license.txt', '#ifndef ADAMIC_REGEXP_FOLD_H', '#define ADAMIC_REGEXP_FOLD_H']
for go, c in [('simpleCaseFold', 'regex_unicode_fold'), ('legacyUppercase', 'regex_legacy_fold')]:
    body = source.split('var ' + go + ' = [...][2]rune{', 1)[1].split('\n}', 1)[0]
    pairs = re.findall(r'\{(0x[0-9a-fA-F]+), (0x[0-9a-fA-F]+)\}', body)
    output.append('static const uint32_t ' + c + '[][2] = {')
    output.extend('{' + a + ',' + b + '},' for a, b in pairs if c != 'regex_legacy_fold' or int(a, 16) <= 65535)
    output.append('};')
output.append('#endif')
(root / 'internal/native/runtime/regexp_fold.h').write_text('\n'.join(output) + '\n')
